using System.IO.Pipes;
using System.Text;
using System.Text.Json;

// mpv started with --input-ipc-server=\\.\pipe\hdrcast-mpv
var pipe = new NamedPipeClientStream(".", "hdrcast-mpv", PipeDirection.InOut, PipeOptions.Asynchronous);
await pipe.ConnectAsync(5000);
var utf8 = new UTF8Encoding(false);
var reader = new StreamReader(pipe, utf8);
var writer = new StreamWriter(pipe, utf8) { AutoFlush = true, NewLine = "\n" };

async Task Cmd(params object[] cmd) =>
    await writer.WriteLineAsync(JsonSerializer.Serialize(new { command = cmd }));

// one observe per stat; the integer is the observer id echoed back in events
await Cmd("observe_property", 1, "demuxer-cache-duration");   // seconds buffered ahead
await Cmd("observe_property", 2, "paused-for-cache");         // true while rebuffering
await Cmd("observe_property", 3, "cache-buffering-state");    // 0-100 % until unpause
await Cmd("observe_property", 4, "frame-drop-count");         // VO drops
await Cmd("observe_property", 5, "decoder-frame-drop-count");
await Cmd("observe_property", 6, "hwdec-current");            // "d3d11va" or "no"
await Cmd("observe_property", 7, "estimated-vf-fps");
await Cmd("observe_property", 8, "video-params");             // node: gamma=pq, primaries=bt.2020, max-luma…
await Cmd("observe_property", 9, "video-target-params");      // what the VO outputs (pq/bt.2020 = passthrough active)
await Cmd("observe_property", 10, "demuxer-cache-state");     // node: raw-input-rate (B/s), fw-bytes, underrun

_ = Task.Run(async () =>
{
    string? line;
    while ((line = await reader.ReadLineAsync()) != null)
    {
        using var doc = JsonDocument.Parse(line);
        var root = doc.RootElement;
        if (root.TryGetProperty("event", out var ev) && ev.GetString() == "property-change")
        {
            var name = root.GetProperty("name").GetString();
            root.TryGetProperty("data", out var data);   // may be missing/null when unavailable
            // marshal to UI thread and update labels
        }
    }
});

// simple catch-up from the host: if buffer > 3.5 s run at 1.05x until <= 2 s
await Cmd("set_property", "speed", 1.05);
await Cmd("set_property", "speed", 1.0);

using System.Runtime.InteropServices;

static class Mpv {
    const string Dll = "libmpv-2.dll";   // from mpv-dev-x86_64-<date>.7z (shinchiro/zhongfly), API 2.5 in 0.40/0.41
    [DllImport(Dll, CallingConvention = CallingConvention.Cdecl)] public static extern IntPtr mpv_create();
    [DllImport(Dll, CallingConvention = CallingConvention.Cdecl)] public static extern int mpv_initialize(IntPtr ctx);
    [DllImport(Dll, CallingConvention = CallingConvention.Cdecl)] public static extern int mpv_set_option_string(IntPtr ctx, [MarshalAs(UnmanagedType.LPUTF8Str)] string name, [MarshalAs(UnmanagedType.LPUTF8Str)] string data);
    [DllImport(Dll, CallingConvention = CallingConvention.Cdecl)] public static extern int mpv_command_string(IntPtr ctx, [MarshalAs(UnmanagedType.LPUTF8Str)] string args);
    [DllImport(Dll, CallingConvention = CallingConvention.Cdecl)] public static extern int mpv_observe_property(IntPtr ctx, ulong userdata, [MarshalAs(UnmanagedType.LPUTF8Str)] string name, int format);
    [DllImport(Dll, CallingConvention = CallingConvention.Cdecl)] public static extern IntPtr mpv_wait_event(IntPtr ctx, double timeout);
    [DllImport(Dll, CallingConvention = CallingConvention.Cdecl)] public static extern void mpv_terminate_destroy(IntPtr ctx);

    public const int FORMAT_STRING = 1, FORMAT_FLAG = 3, FORMAT_INT64 = 4, FORMAT_DOUBLE = 5, FORMAT_NODE = 6;
    public const int EVENT_SHUTDOWN = 1, EVENT_END_FILE = 7, EVENT_PROPERTY_CHANGE = 22;

    [StructLayout(LayoutKind.Sequential)] public struct Event { public int event_id; public int error; public ulong reply_userdata; public IntPtr data; }
    [StructLayout(LayoutKind.Sequential)] public struct EventProperty { public IntPtr name; public int format; public IntPtr data; }
}

// usage (WinForms Panel `video`):
var ctx = Mpv.mpv_create();
Mpv.mpv_set_option_string(ctx, "wid", video.Handle.ToInt64().ToString());
Mpv.mpv_set_option_string(ctx, "vo", "gpu-next");
Mpv.mpv_set_option_string(ctx, "gpu-api", "d3d11");
Mpv.mpv_set_option_string(ctx, "hwdec", "d3d11va");
Mpv.mpv_set_option_string(ctx, "target-colorspace-hint", "auto");
Mpv.mpv_set_option_string(ctx, "cache-pause-initial", "yes");
Mpv.mpv_set_option_string(ctx, "cache-pause-wait", "1.5");
Mpv.mpv_initialize(ctx);
Mpv.mpv_observe_property(ctx, 1, "demuxer-cache-duration", Mpv.FORMAT_DOUBLE);
Mpv.mpv_observe_property(ctx, 2, "frame-drop-count", Mpv.FORMAT_INT64);
Mpv.mpv_command_string(ctx, "loadfile \"srt://relay:8890?mode=caller&latency=1500000&streamid=read:hdrcast\"");
// event thread:
while (true) {
    var ev = Marshal.PtrToStructure<Mpv.Event>(Mpv.mpv_wait_event(ctx, 1.0));
    if (ev.event_id == Mpv.EVENT_SHUTDOWN) break;
    if (ev.event_id == Mpv.EVENT_PROPERTY_CHANGE) {
        var p = Marshal.PtrToStructure<Mpv.EventProperty>(ev.data);
        if (p.format == Mpv.FORMAT_DOUBLE && p.data != IntPtr.Zero) { double v = Marshal.PtrToStructure<double>(p.data); /* userdata==1 → cache secs */ }
        if (p.format == Mpv.FORMAT_INT64  && p.data != IntPtr.Zero) { long  v = Marshal.PtrToStructure<long>(p.data); }
    }
}
